results.query:
query a: party, e: entity, kr: bitstring, ke: bitstring, n: bitstring, id: identity, t: tcbstatus, x: polstar, body: bitstring;
  event(CertIssued(a,e,kr,ke,n,id,t,x,body)) ==>
    event(Confirm(a,x)) && event(ChallengeSent(a,ke,n)) && event(QuoteProduced(ke,n,id,t)) && body = H((ke,kr,H(starBytes(x)))).

